import zlib, base64, json
from matplotlib.patches import Polygon

# Batas kecamatan Kabupaten Kotabaru (GADM 4.1, sudah disederhanakan) disimpan di dalam skrip ini,
# jadi tidak perlu file lain dan tetap jalan saat dashboard dipublikasikan.
PETA = json.loads(zlib.decompress(base64.b64decode("")).decode())

d = dataset.copy()
per_kec = d.groupby(["Kecamatan", "Nama Peta"], as_index=False).agg({"Total Penjualan": "sum", "Penduduk": "max"})
per_kec = per_kec[per_kec["Total Penjualan"].fillna(0) > 0]   # buang baris kecamatan tanpa penjualan
per_kec["Per Jiwa"] = per_kec["Total Penjualan"] / per_kec["Penduduk"]
per_peta = per_kec.groupby("Nama Peta")["Total Penjualan"].sum()
tot = per_kec["Total Penjualan"].sum()
cmap = plt.matplotlib.colors.LinearSegmentedColormap.from_list("b", ["#CDE2FB", "#6DA7EC", "#2A78D6", "#104281"])
norm = plt.matplotlib.colors.Normalize(0, per_peta.max())
def warna(nama): return cmap(norm(per_peta[nama])) if nama in per_peta.index else "#F1F0EC"

fig = plt.figure()
ax = fig.add_axes([0.0, 0.11, 0.46, 0.78])
for nama, cincin in PETA.items():
    for r in cincin:
        ax.add_patch(Polygon(r, closed=True, facecolor=warna(nama), edgecolor="white", lw=0.6))
ax.set_xlim(115.45, 116.62); ax.set_ylim(-4.80, -2.25); ax.set_aspect("equal"); ax.set_axis_off()

ax2 = fig.add_axes([0.50, 0.11, 0.50, 0.78]); ax2.set_axis_off(); ax2.set_xlim(0, 1); ax2.set_ylim(0, 1)
urut = per_kec.sort_values("Total Penjualan", ascending=False).reset_index(drop=True)
for i, r in urut.iterrows():
    y = 0.93 - i * 0.135
    ax2.add_patch(plt.Rectangle((0.0, y - 0.035), 0.05, 0.07, color=warna(r["Nama Peta"]), transform=ax2.transAxes))
    ax2.text(0.08, y + 0.025, r["Kecamatan"], fontsize=8.2, fontweight="bold" if i == 0 else "normal", va="center")
    ax2.text(0.08, y - 0.03, "%s (%s) · Rp%s/jiwa" % (jt(r["Total Penjualan"]), pct(r["Total Penjualan"] / tot), format(int(round(r["Per Jiwa"])), ",").replace(",", ".")),
             fontsize=7.2, color=INK2, va="center")
fig.suptitle(textwrap.fill("4 · %s terbesar: %s penjualan" % (urut.loc[0, "Kecamatan"], pct(urut.loc[0, "Total Penjualan"] / tot)), 70),
             x=0.01, ha="left", fontsize=10.5, fontweight="bold")
catatan(fig, "Warna = total penjualan. Abu-abu = belum ada transaksi. P. Laut Sigam belum terpisah di peta GADM, warnanya digabung dengan P. Laut Utara.")
plt.show()
